package example;

// Assuming these Eclipse APIs are available on the classpath for compilation
// in the sandbox environment, as stubbing them is disallowed by rules.
interface ILaunchConfiguration {
    boolean getAttribute(String name, boolean defaultValue);
    void setAttribute(String name, boolean value);
    void setAttribute(String name, String value);
}

class CoreException extends Exception {
    public CoreException(String message) { super(message); }
}

// Original constant location
class IDebugUIConstants {
    public static final String ATTR_MERGE_OUTPUT = "org.eclipse.debug.ui.ATTR_MERGE_OUTPUT";
    public static final String ATTR_CAPTURE_IN_FILE = "org.eclipse.debug.ui.ATTR_CAPTURE_IN_FILE";
}

public class MyLaunchConfigurationTab {
    public void performApply(ILaunchConfiguration configuration) throws CoreException {
        boolean mergeOutput;
        mergeOutput = configuration.getAttribute(IDebugUIConstants.ATTR_MERGE_OUTPUT, false);
        configuration.setAttribute(IDebugUIConstants.ATTR_MERGE_OUTPUT, true);
        configuration.setAttribute(IDebugUIConstants.ATTR_MERGE_OUTPUT, (String) null);
        System.out.println("Current merge output setting: " + mergeOutput);
    }
}

